// Register handles user registration
func (r *mutationResolver) Register(ctx context.Context, name string, username string, email *string, password string) (*model.AuthResponse, error) {
	log.Println("Registering new user...")

	// Ensure username is unique
	var existing model.UserDB
	if err := r.DB.Where("username = ?", username).First(&existing).Error; err == nil {
		return nil, errors.New("username already in use")
	} else if !errors.Is(err, gorm.ErrRecordNotFound) {
		return nil, fmt.Errorf("error checking username: %v", err)
	}
	// Ensure email (if provided) is unique
	if email != nil && *email != "" {
		var byEmail model.UserDB
		if err := r.DB.Where("email = ?", *email).First(&byEmail).Error; err == nil {
			return nil, errors.New("email already in use")
		} else if !errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("error checking email: %v", err)
		}
	}

	// Hash password
	hashedPassword, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return nil, fmt.Errorf("error hashing password: %v", err)
	}

	// Create new user
	user := model.UserDB{
		Name:     name,
		Username: username,
		Password: string(hashedPassword),
		IsActive: true,
	}
	if email != nil {
		user.Email = *email
	}

	if err := r.DB.Create(&user).Error; err != nil {
		log.Printf("register: DB create error: %v", err)
		return nil, err
	}

	token, err := generateJWT(int32(user.ID), user.Username)
	if err != nil {
		log.Printf("register: token generation failed: %v", err)
		return nil, errors.New("failed to generate token")
	}

	// Convert to GraphQL model
	userModel := toGraphQLUser(user)

	return &model.AuthResponse{
		Token: token,
		User:  userModel,
	}, nil
}

// Login handles user login and returns a JWT token
func (r *mutationResolver) Login(ctx context.Context, username string, password string) (*model.AuthResponse, error) {
	// Find user by username
	var user model.UserDB
	if err := r.DB.Where("username = ?", username).First(&user).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, errors.New("invalid username or password")
		}
		return nil, fmt.Errorf("error finding user: %v", err)
	}

	// Check password
	if err := bcrypt.CompareHashAndPassword([]byte(user.Password), []byte(password)); err != nil {
		return nil, errors.New("invalid username or password")
	}

	// Generate JWT token
	token, err := generateJWT(int32(user.ID), user.Username)
	if err != nil {
		return nil, errors.New("failed to generate token")
	}

	// Convert to GraphQL model
	userModel := toGraphQLUser(user)

	return &model.AuthResponse{
		Token: token,
		User:  userModel,
	}, nil
}

