// UpdateUserAvatar is the resolver for the updateUserAvatar field.
// Accepts a base64 string and returns the public URL string after saving.
func (r *mutationResolver) UpdateUserAvatar(ctx context.Context, id int32, avatar string) (string, error) {
	var u model.UserDB
	if err := r.DB.Where("id = ?", id).First(&u).Error; err != nil {
		return "", err
	}

	// Ensure upload directory exists
	uploadDir := "uploads/avatars"
	if err := os.MkdirAll(uploadDir, os.ModePerm); err != nil {
		return "", fmt.Errorf("failed to create upload directory: %w", err)
	}

	// If no avatar data was provided, return the current avatar URL
	if avatar == "" {
		return u.Avatar, nil
	}

	// Process the base64 string
	// Remove data:image/...;base64, prefix if present
	base64Data := avatar
	if idx := strings.Index(avatar, "base64,"); idx != -1 {
		base64Data = avatar[idx+7:] // +7 to skip "base64,"
	}

	// Decode base64 string to bytes
	data, err := base64.StdEncoding.DecodeString(base64Data)
	if err != nil {
		return "", fmt.Errorf("invalid base64 data: %w", err)
	}

	// Determine file extension from content type or default to png
	extension := "png"
	if strings.Contains(avatar, "image/jpeg") || strings.Contains(avatar, "image/jpg") {
		extension = "jpg"
	} else if strings.Contains(avatar, "image/gif") {
		extension = "gif"
	}

	// Create unique filename and path
	filename := fmt.Sprintf("%d_%d.%s", id, time.Now().Unix(), extension)
	filePath := filepath.Join(uploadDir, filename)

	// Save file to disk
	if err := os.WriteFile(filePath, data, 0644); err != nil {
		return "", fmt.Errorf("failed to save file: %w", err)
	}

	// Build URL (adjust static serving accordingly)
	fileURL := fmt.Sprintf("/uploads/avatars/%s", filename)

	// Store URL in DB
	u.Avatar = fileURL
	if err := r.DB.Save(&u).Error; err != nil {
		// Try to clean up the file if DB update fails
		os.Remove(filePath)
		return "", fmt.Errorf("failed to update user: %w", err)
	}

	return fileURL, nil
}

